def file_name_check(file_name):
    # Check if there are more than 3 digits
    if len(file_name) > 3:
        return "No"

    # Check if there's exactly one dot
    if '.' not in file_name:
        return "No"

    # Split the file name into parts
    parts = file_name.split('.')

    # Check that there's exactly one part (should be 2 parts)
    if len(parts) != 2:
        return "No"

    # Check that the first part starts with a letter (a-z, A-Z)
    if not parts[0].isalpha():
        return "No"

    # Check that the second part is one of the valid extensions
    if parts[1] not in ['txt', 'exe', 'dll']:
        return "No"

    return "Yes"
